@app.post("/kyc/upload")
def upload_kyc(telegram_id: int, file_url: str, db: Session = Depends(get_db)):
    db_user = db.query(User).filter(User.telegram_id == telegram_id).first()
    if not db_user:
        raise HTTPException(status_code=404, detail="User not found")
    
    # Store in S3 (mocked for now)
    # In production: s3_client.upload_fileobj(file, S3_BUCKET, f"kyc/{telegram_id}")
    db_user.kyc_doc_url = file_url
    db_user.kyc_status = "pending"
    db.commit()
    return {"status": "KYC uploaded", "url": file_url}

@app.post("/groups/", response_model=GroupResponse)
def create_group(group: GroupCreate, db: Session = Depends(get_db)):
    # Validate fees against platform limits
    for fee_type, fee_value in group.dict().items():
        if fee_type in platform_limits and fee_value is not None and fee_value > platform_limits[fee_type]:
            raise HTTPException(status_code=400, detail=f"{fee_type} exceeds platform limit")
    
    db_group = Group(**group.dict())
    db.add(db_group)
    db.commit()
    db.refresh(db_group)
    return db_group

@app.post("/contributions/", response_model=ContributionResponse)
def create_contribution(contribution: ContributionCreate, db: Session = Depends(get_db)):
    db_group = db.query(Group).filter(Group.id == contribution.group_id).first()
    if not db_group:
        raise HTTPException(status_code=404, detail="Group not found")
    
    # Calculate admin fee
    admin_fee = 0
    if db_group.fixed_fee:
        admin_fee += db_group.fixed_fee
    if db_group.percentage_fee:
        admin_fee += contribution.amount * (db_group.percentage_fee / 100)
    # Add other fee types as needed
    
    # Update user wallet
    db_user = db.query(User).filter(User.id == contribution.user_id).first()
    if db_user.wallet_balance < (contribution.amount + admin_fee):
        raise HTTPException(status_code=400, detail="Insufficient funds")
    
    db_user.wallet_balance -= (contribution.amount + admin_fee)
    db.add(Contribution(**contribution.dict(), admin_fee=admin_fee))
    db.add(WalletTransaction(
        user_id=contribution.user_id,
        amount=-(contribution.amount + admin_fee),
        type="contribution",
        group_id=contribution.group_id
    ))
    db.commit()
    return ContributionResponse(id=1, **contribution.dict(), admin_fee=admin_fee, timestamp=datetime.utcnow())

